#!/bin/bash
# Uninstall script for Oracle VirtualBox
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Oracle VirtualBox..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Oracle VirtualBox if running..."
pkill -f "Oracle VirtualBox" 2>/dev/null || true

# Remove /Library/Application Support/VirtualBox
echo "Removing /Library/Application Support/VirtualBox..."
if [ -d "/Library/Application Support/VirtualBox" ]; then
    rm -rf "/Library/Application Support/VirtualBox" 2>/dev/null || true
elif [ -f "/Library/Application Support/VirtualBox" ]; then
    rm -f "/Library/Application Support/VirtualBox" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.virtualbox.app.virtualbox*
echo "Removing $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.virtualbox.app.virtualbox*..."
if [ -d "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.virtualbox.app.virtualbox*" ]; then
    rm -rf "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.virtualbox.app.virtualbox*" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.virtualbox.app.virtualbox*" ]; then
    rm -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.virtualbox.app.virtualbox*" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/org.virtualbox.app.VirtualBox*
echo "Removing $HOME/Library/Preferences/org.virtualbox.app.VirtualBox*..."
if [ -d "$HOME/Library/Preferences/org.virtualbox.app.VirtualBox*" ]; then
    rm -rf "$HOME/Library/Preferences/org.virtualbox.app.VirtualBox*" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/org.virtualbox.app.VirtualBox*" ]; then
    rm -f "$HOME/Library/Preferences/org.virtualbox.app.VirtualBox*" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/org.virtualbox.app.VirtualBox*
echo "Removing $HOME/Library/Saved Application State/org.virtualbox.app.VirtualBox*..."
if [ -d "$HOME/Library/Saved Application State/org.virtualbox.app.VirtualBox*" ]; then
    rm -rf "$HOME/Library/Saved Application State/org.virtualbox.app.VirtualBox*" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/org.virtualbox.app.VirtualBox*" ]; then
    rm -f "$HOME/Library/Saved Application State/org.virtualbox.app.VirtualBox*" 2>/dev/null || true
fi

# Remove $HOME/Library/VirtualBox
echo "Removing $HOME/Library/VirtualBox..."
if [ -d "$HOME/Library/VirtualBox" ]; then
    rm -rf "$HOME/Library/VirtualBox" 2>/dev/null || true
elif [ -f "$HOME/Library/VirtualBox" ]; then
    rm -f "$HOME/Library/VirtualBox" 2>/dev/null || true
fi

# Remove $HOME/VirtualBox VMs
echo "Removing $HOME/VirtualBox VMs..."
if [ -d "$HOME/VirtualBox VMs" ]; then
    rm -rf "$HOME/VirtualBox VMs" 2>/dev/null || true
elif [ -f "$HOME/VirtualBox VMs" ]; then
    rm -f "$HOME/VirtualBox VMs" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
